p = source("RovexHomeRevolution.kt")
s = p.read_text()
anchor = '    private fun d(v:Int,c:Context)=(v*c.resources.displayMetrics.density).toInt()\n'
helpers = """    private const val MOTION_BG_TAG = "rovex_home_motion_background"
    private const val MOTION_CARD_PREFIX = "rovex_home_motion_card:"
    private var motionPolicyAllowed = true
    private fun motionAlpha(c:Context, background:Boolean):Float {
        val card = when (ThemeManager.get(c)) {
            ThemeManager.LIGHT -> 0.22f
            ThemeManager.PASTEL -> 0.20f
            ThemeManager.MINT -> 0.18f
            ThemeManager.SUNSET -> 0.20f
            ThemeManager.LAVENDER -> 0.20f
            ThemeManager.AMOLED -> 0.12f
            ThemeManager.PANDORA -> 0.14f
            ThemeManager.SPACE -> 0.12f
            else -> 0.16f
        }
        return if (background) card * 0.42f else card
    }

    private fun motionBackground(c:Context, tagValue:String, background:Boolean=false):LottieAnimationView? {
        if (!motionPolicyAllowed) return null
        val view = LottieAnimationView(c).apply {
            tag = tagValue
            setAnimation("rovex/motion/gradient_animated_background.json")
            repeatCount = LottieDrawable.INFINITE
            repeatMode = LottieDrawable.RESTART
            speed = 0.38f
            alpha = motionAlpha(c, background)
            scaleType = ImageView.ScaleType.CENTER_CROP
            renderMode = RenderMode.HARDWARE
            isClickable = false
            isFocusable = false
            importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_NO
            contentDescription = null
        }
        view.addOnAttachStateChangeListener(object : View.OnAttachStateChangeListener {
            override fun onViewAttachedToWindow(v:View) {
                v.post { updateMotionView(view, c) }
            }
            override fun onViewDetachedFromWindow(v:View) {
                runCatching { view.cancelAnimation() }
            }
        })
        return view
    }

    private fun updateMotionView(view:LottieAnimationView, c:Context, forcePause:Boolean=false) {
        val tag = view.tag as? String ?: return
        if (tag != MOTION_BG_TAG && !tag.startsWith(MOTION_CARD_PREFIX)) return
        view.alpha = motionAlpha(c, tag == MOTION_BG_TAG)
        val visibleRect = android.graphics.Rect()
        val visible = !forcePause && view.isShown &&
            view.getGlobalVisibleRect(visibleRect) && visibleRect.width() > 0 && visibleRect.height() > 0
        if (visible && motionPolicyAllowed) runCatching { view.resumeAnimation() }
        else runCatching { view.pauseAnimation() }
    }

    private fun updateMotionTree(view:View, c:Context, forcePause:Boolean=false) {
        if (view is LottieAnimationView) updateMotionView(view, c, forcePause)
        if (view is ViewGroup) for (i in 0 until view.childCount) updateMotionTree(view.getChildAt(i), c, forcePause)
    }

    fun pauseMotion(a:MainActivity) {
        val root = a.findViewById<ViewGroup>(R.id.dashboardRoot) ?: return
        root.findViewWithTag<FrameLayout>(TAG)?.let { updateMotionTree(it, a, true) }
    }

"""
