old_box = '''        val box=FrameLayout(a).apply{background=card(a,index);setPadding(d(14,a),d(13,a),d(10,a),d(10,a));isClickable=true;isFocusable=true;elevation=d(4,a).toFloat();setOnClickListener{target()}}
        val col=LinearLayout(a).apply{orientation=LinearLayout.VERTICAL}'''
new_box = '''        val box=FrameLayout(a).apply{background=card(a,index);setPadding(d(14,a),d(13,a),d(10,a),d(10,a));isClickable=true;isFocusable=true;elevation=d(4,a).toFloat();setOnClickListener{target()}}
        motionBackground(a, MOTION_CARD_PREFIX + title)?.let { motion ->
            val clip = FrameLayout(a).apply {
                background = GradientDrawable().apply { cornerRadius = d(22,a).toFloat(); setColor(Color.TRANSPARENT) }
                clipToOutline = true
                importantForAccessibility = View.IMPORTANT_FOR_ACCESSIBILITY_NO
            }
            clip.addView(motion, FrameLayout.LayoutParams(-1,-1))
            box.addView(clip, FrameLayout.LayoutParams(-1,-1).apply {
                leftMargin = -d(14,a); topMargin = -d(13,a); rightMargin = -d(10,a); bottomMargin = -d(10,a)
            })
        }
        val col=LinearLayout(a).apply{orientation=LinearLayout.VERTICAL}'''
if old_box not in s: raise SystemExit("[637] feature card insertion anchor missing")
s = s.replace(old_box, new_box, 1)

old_shell = '''        val shell=FrameLayout(a).apply{tag=TAG;contentDescription="rovexHomeShell";background=if (ThemeManager.get(a) == ThemeManager.LIGHT) RovexClinicalDayHomeBackgroundDrawable(a) else ThemeManager.backgroundDrawable(a)}
        val scroll=ScrollView(a).apply{tag="ROVEX_HOME_SCROLL";overScrollMode=View.OVER_SCROLL_NEVER;clipToPadding=false;isFillViewport=true}'''
new_shell = '''        motionPolicyAllowed = AnimationPolicy.enabled(a)
        val shell=FrameLayout(a).apply{tag=TAG;contentDescription="rovexHomeShell";background=if (ThemeManager.get(a) == ThemeManager.LIGHT) RovexClinicalDayHomeBackgroundDrawable(a) else ThemeManager.backgroundDrawable(a)}
        motionBackground(a, MOTION_BG_TAG, true)?.let { shell.addView(it, FrameLayout.LayoutParams(-1,-1)) }
        val scroll=ScrollView(a).apply{tag="ROVEX_HOME_SCROLL";overScrollMode=View.OVER_SCROLL_NEVER;clipToPadding=false;isFillViewport=true}
        scroll.setOnScrollChangeListener { _, _, _, _, _ -> updateMotionTree(shell, a) }'''
if old_shell not in s: raise SystemExit("[637] Home shell insertion anchor missing")
s = s.replace(old_shell, new_shell, 1)

root_anchor = '        root.addView(shell,ViewGroup.LayoutParams(-1,-1))\n'
if root_anchor not in s: raise SystemExit("[637] root attach anchor missing")
s = s.replace(root_anchor, root_anchor + '        shell.post { updateMotionTree(shell, a) }\n', 1)
p.write_text(s)

m = source("MainActivity.kt")
ms = m.read_text()
old_pause = '    override fun onPause(){ super.onPause() }'
new_pause = '    override fun onPause(){ RovexHomeRevolution.pauseMotion(this); super.onPause() }'
if old_pause not in ms: raise SystemExit("[637] MainActivity onPause anchor missing")
