# Structural postconditions catch a silent/partial overlay before the build starts.
home = (PKG / "RovexHomeRevolution.kt").read_text()
main = (PKG / "MainActivity.kt").read_text()
if "gradient_animated_background.json" not in home or "updateMotionTree(shell, a)" not in home:
    raise SystemExit("[637] imported Lottie background/card motion was not wired")
