if "gradient_animated_background.json" not in MANIFEST.read_text():
    raise SystemExit("[637] external motion asset is missing from the manifest")

print("[637] applied v8.3.637 / versionCode 723")
print(f"[637] imported Lottie background JSON ({len(asset_data.encode('utf-8'))} bytes, sha256={asset_sha}) with explicit license/source record")
